".pmt": { n:"WorksheetFunction.Pmt", f:"…Pmt(tasa, nper, va)", q:"La cuota de un préstamo (sale negativa: es un pago). En la hoja: =ROUND(-PMT(D2/12,E2,C2),2).",
  p:[["tasa","Tasa del período: tasa anual / 12."],["nper","Número de cuotas."],["va","Monto del préstamo."]], xl:"PMT / PAGO", src:"Clase E3b, Guía E7" },
