/* ---------- Arreglos y colecciones ---------- */
"lbound": { n:"LBound", f:"LBound(arreglo)", q:"El primer índice del arreglo (0 o 1). Con Split empieza en 0; con un rango leído de la hoja, en 1." },
"preserve": { n:"ReDim Preserve", f:"ReDim Preserve lista(1 To n)", q:"Agranda un arreglo sin perder lo que ya tenía. Sirve para listas cuyo tamaño no se conoce antes (los pendientes).",
  ej:"n = n + 1\nReDim Preserve lista(1 To n)\nlista(n) = datos(i, 1)", tr:"Solo puede cambiar la ÚLTIMA dimensión. Si n queda en 0, no hagas ReDim (1 To 0 da error): revisá antes si hubo alguno.", src:"Clase E4b" },
"split": { n:"Split", f:"Split(texto, separador)(posición)",
  q:"Parte el texto en un arreglo usando el separador. Las posiciones empiezan en 0.",
  p:[["texto","El texto a partir."],["separador","Dónde cortar: \"-\", \"@\", \"/\"."],["(posición)","Cuál pedazo: (0) el primero, (1) el segundo…"]],
  ej:"partes = Split(\"VEN-GT-031\", \"-\")\npartes(0)   ' \"VEN\"\npartes(1)   ' \"GT\"", py:"texto.split(sep)[i]",
  tr:"Empieza en 0, no en 1 como las celdas o los arreglos leídos de la hoja.", src:"Clase E2b, Guía E12" },
".remove": { n:".Remove", f:"col.Remove índice · dic.Remove clave", q:"Quita un elemento de una Collection (por posición o clave) o una clave de un Dictionary." },
