".comparemode": { n:".CompareMode", f:"d.CompareMode = vbTextCompare", q:"Hace que el Dictionary no distinga mayúsculas: \"Hogar\" y \"HOGAR\" serían la misma clave. Se pone ANTES de agregar claves." },
"clave": { n:"Collection con clave (sin repetidos)", f:"On Error Resume Next\ncol.Add nombre, nombre   ' valor, clave\nOn Error GoTo 0",
  q:"Al agregar a una Collection podés darle una clave. Si la clave ya existe da error, y ese error se aprovecha: con On Error Resume Next el repetido simplemente no entra.",
  tr:"Volvé a encender los errores con On Error GoTo 0 apenas termine el bucle; si no, cualquier otro error queda escondido.", src:"Clase E4c" },

/* ---------- Errores y depuración ---------- */
"on": { n:"On Error", f:"On Error Resume Next · On Error GoTo 0 · On Error GoTo Etiqueta",
  q:"Controla qué pasa cuando hay un error. Resume Next: sigue con la línea siguiente. GoTo 0: vuelve al comportamiento normal. GoTo Etiqueta: salta a un bloque que maneja el error.",
  ej:"On Error Resume Next\nSet h = Worksheets(\"Resumen\")   ' si no existe, h queda Nothing\nOn Error GoTo 0\nIf h Is Nothing Then …",
  tr:"Resume Next esconde TODOS los errores: encerralo en las pocas líneas que lo necesitan.", src:"Clase E4c, Guía E14" },
"error": { al:"on" }, "resume": { al:"on" },
"err": { n:"Err", f:"Err.Number · Err.Description", q:"El último error ocurrido. Err.Number es 0 si no hubo error. Después de On Error Resume Next se revisa If Err.Number <> 0." },
"goto": { n:"GoTo", f:"GoTo Etiqueta\n…\nEtiqueta:", q:"Salta a una línea con etiqueta (un nombre seguido de dos puntos). Se usa para validaciones o manejo de errores.", tr:"Poné Exit Sub antes de la etiqueta para que la macro no caiga ahí cuando todo sale bien." },
"isempty": { n:"IsEmpty", f:"IsEmpty(celda.Value)", q:"True si la celda está vacía.",
  tr:"IsNumeric de una celda vacía da True. Para validar un número: Not IsEmpty(x) And IsNumeric(x).", src:"Clase E2d" },
"stop": { n:"Stop y puntos de interrupción", f:"Stop · F9 · F8", q:"Stop pausa la macro en esa línea. F9 pone un punto de interrupción; F8 ejecuta línea por línea; pasando el mouse sobre una variable ves su valor." },

