".screenupdating": { n:"ScreenUpdating", f:"Application.ScreenUpdating = False … True", q:"Apaga el redibujo de la pantalla mientras la macro trabaja: mucho más rápido con miles de filas. Volvé a True al final." },
".calculation": { n:"Calculation", f:"Application.Calculation = xlCalculationManual … xlCalculationAutomatic", q:"Detiene el recálculo de fórmulas mientras la macro escribe. Restaurar a automático al final." },
".enableevents": { n:"EnableEvents", f:"Application.EnableEvents = False … True", q:"Apaga los eventos. Dentro de Worksheet_Change evita que tu propia escritura vuelva a disparar el evento.", tr:"Si la macro se detiene con EnableEvents en False, los eventos quedan apagados: en Immediate escribí Application.EnableEvents = True." },
"worksheet_change": { n:"Worksheet_Change", f:"Private Sub Worksheet_Change(ByVal Target As Range)", q:"Se ejecuta solo cada vez que el usuario cambia una celda de esa hoja. Va en el módulo de la HOJA (doble clic en la hoja en el editor), no en un módulo normal.", src:"Segmento 14" },
